import { Injectable, inject, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, map, catchError, of } from 'rxjs';
import { NuevaObservacionInput, Observacion } from '../models/observacion.model';
import { environment } from '../../../environments/environment';
interface ObservacionListResponse {
  data: Observacion[];
}

interface ObservacionSingleResponse {
  data: Observacion;
  message?: string;
}

interface ObservacionStoreResponse {
  data: { observacion: Observacion; status: string };
  message: string;
}

interface EnviarObservacionesResponse {
  data: { status: string };
  message: string;
}

@Injectable({ providedIn: 'root' })
export class ObservacionesService {
  private readonly http = inject(HttpClient);

  private readonly store = signal<Record<string, Observacion[]>>({});

  observacionesDe(folio: string): Observacion[] {
    return this.store()[folio] ?? [];
  }

  cargar(folio: string): void {
    this.http
      .get<ObservacionListResponse>(`${environment.apiUrl}/solicitudes/${folio}/observaciones`)
      .pipe(
        catchError(() => of({ data: [] as Observacion[] })),
      )
      .subscribe((res) => this.store.update((store) => ({ ...store, [folio]: res.data })));
  }

  agregar(folio: string, input: NuevaObservacionInput): Observable<{ status: string; message: string }> {
    const payload = {
      texto: input.texto,
      target: input.target,
    };

    return this.http
      .post<ObservacionStoreResponse>(
        `${environment.apiUrl}/solicitudes/${folio}/observaciones`,
        payload,
      )
      .pipe(
        map((res) => {
          const actuales = this.store()[folio] ?? [];
          this.store.set({ ...this.store(), [folio]: [...actuales, res.data.observacion] });

          return { status: res.data.status, message: res.message };
        }),
      );
  }

  marcarCorregida(folio: string, id: number): Observable<void> {
    return this.http
      .patch<ObservacionSingleResponse>(
        `${environment.apiUrl}/observaciones/${id}`,
        { status: 'corregida' },
      )
      .pipe(
        map((res) => {
          this.store.update((store) => ({
            ...store,
            [folio]: (store[folio] ?? []).map((o) =>
              o.id === id ? { ...o, status: res.data.status } : o,
            ),
          }));

          return undefined;
        }),
      );
  }

  marcarAtendida(folio: string, id: number): Observable<void> {
    return this.http
      .patch<ObservacionSingleResponse>(
        `${environment.apiUrl}/observaciones/${id}`,
        { status: 'atendida' },
      )
      .pipe(
        map((res) => {
          this.store.update((store) => ({
            ...store,
            [folio]: (store[folio] ?? []).map((o) =>
              o.id === id ? { ...o, status: res.data.status } : o,
            ),
          }));

          return undefined;
        }),
      );
  }

  eliminar(folio: string, id: number): Observable<void> {
    return this.http
      .delete(`${environment.apiUrl}/observaciones/${id}`)
      .pipe(
        map(() => {
          this.store.update((store) => ({
            ...store,
            [folio]: (store[folio] ?? []).filter((o) => o.id !== id),
          }));
          return undefined;
        }),
      );
  }

  editar(id: number, data: { texto: string }, folio: string): Observable<void> {
    return this.http
      .patch(`${environment.apiUrl}/observaciones/${id}`, data)
      .pipe(
        map(() => {
          this.store.update((store) => ({
            ...store,
            [folio]: (store[folio] ?? []).map((o) =>
              o.id === id ? { ...o, texto: data.texto } : o,
            ),
          }));
          return undefined;
        }),
      );
  }

  enviarObservaciones(folio: string): Observable<void> {
    return this.http
      .post<EnviarObservacionesResponse>(
        `${environment.apiUrl}/solicitudes/${folio}/enviar-observaciones`,
        {},
      )
      .pipe(
        map(() => undefined),
      );
  }

  enviarCorreccionesInversor(folio: string): Observable<void> {
    return this.http
      .post<EnviarObservacionesResponse>(
        `${environment.apiUrl}/solicitudes/${folio}/subsanar`,
        {},
      )
      .pipe(
        map(() => undefined),
      );
  }

  subsanarTramites(folio: string): Observable<void> {
    return this.http
      .post<EnviarObservacionesResponse>(
        `${environment.apiUrl}/solicitudes/${folio}/subsanar-tramites`,
        {},
      )
      .pipe(
        map(() => undefined),
      );
  }

  restablecer(): void {
    this.store.set({});
  }
}
